/// <summary>
/// post staging get data method
/// </summary>
/// <param name = "_dmfDefinitionGroupExecution">DMFDefinitionGroupExecution record</param>
public static void postGetStagingData(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    NDXRequisitionLineStaging lNDXRequisitionLineStaging;
    NDXExcelDMFImportParameters lNDXExcelDMFImportParameters = NDXExcelDMFImportParameters::find(_dmfDefinitionGroupExecution.RecId);

    NDXRequisition ndxRequisition = NDXRequisition::find(conPeek(lNDXExcelDMFImportParameters.Parameters, 1));

    int lastlevel = NDXRequisitionLine::getMaxLevel(ndxRequisition.RequisitionId);

    while select forupdate lNDXRequisitionLineStaging
        where lNDXRequisitionLineStaging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
            && lNDXRequisitionLineStaging.ExecutionId == _dmfDefinitionGroupExecution.ExecutionId
            && lNDXRequisitionLineStaging.TransferStatus == DMFTransferStatus::NotStarted
    {
        ttsbegin;
        lNDXRequisitionLineStaging.Level1 = 1;
        lNDXRequisitionLineStaging.Level = lastlevel;
        lNDXRequisitionLineStaging.LevelString = Con2Str([lNDXRequisitionLineStaging.Level], '.');

        lNDXRequisitionLineStaging.RequisitionId = ndxRequisition.RequisitionId;
        lNDXRequisitionLineStaging.doUpdate();
        ttscommit;

        lastlevel++;
    }
}
